function parse(url) {
  const output = {
    protocols: [],
    protocol: null,
    port: null,
    resource: "",
    user: "",
    password: "",
    pathname: "",
    hash: "",
    search: "",
    href: url,
    query: {}
  };

  try {
    const parsed = new URL(url);
    // Validate allowed protocols to prevent sensitive ones like file://
    const allowedProtocols = ['http:', 'https:'];
    if (!allowedProtocols.includes(parsed.protocol)) {
      throw new Error('Unsupported protocol: ' + parsed.protocol);
