func isAllowedToRun(uid uint32, args []string) bool {
	// A command can run if any of the following are true:
	//	* It runs as root
	//	* It's a global help command (-h/--help with no other arguments)
	//	* It's contained in nonRootAllowed
	//	* It's used with the -h or --help flags and the main command is in nonRootAllowed
	// note: commands still need valid context and snaps can only access own config.
	return uid == 0 ||
		(len(args) == 1 && (args[0] == "-h" || args[0] == "--help")) ||
		strutil.ListContains(nonRootAllowed, args[0]) ||
		(strutil.ListContains(args, "-h") && strutil.ListContains(nonRootAllowed, args[0])) ||
		(strutil.ListContains(args, "--help") && strutil.ListContains(nonRootAllowed, args[0]))
}

