func isOriginAllowed(allows []string, origin string) bool {
	for _, o := range allows {
		if o == allOrigins {
			return true
		}
		// Extract hostname from origin (excluding protocol and port)
		originParts := strings.SplitN(origin, "://", 2)
		if len(originParts) != 2 {
			continue
		}
		hostParts := strings.SplitN(originParts[1], ":", 2)
		hostname := hostParts[0]
		// Handle IPv6 addresses (remove brackets)
		if strings.Contains(hostname, "]") {
			hostname = strings.Trim(hostname, "[]")
		}
		// Convert to lowercase for case-insensitive comparison
		hostname = strings.ToLower(hostname)
		allowedOrigin := strings.ToLower(o)
		// Check for subdomain wildcard (e.g., ".example.com")
		if strings.HasPrefix(allowedOrigin, ".") {
			if strings.HasSuffix(hostname, allowedOrigin) {
				return true
			}
		} else {
			// Exact hostname match (e.g., "example.com")
			if hostname == allowedOrigin {
				return true
			}
		}
	}
	return false
}

