	//lint:ignore faillint wrapper around upstream method
	orgID, err := user.ExtractOrgID(ctx)
	if err != nil {
		return nil, err
	}
	// Validate orgID to prevent directory traversal in file paths
	if orgID == "" {
		return nil, errors.New("invalid orgID: empty string")
	}
	if filepath.IsAbs(orgID) {
		return nil, errors.New("invalid orgID: absolute path not allowed")
	}
	segments := strings.Split(orgID, string(os.PathSeparator))
	for _, seg := range segments {
		switch seg {
		case "":
			return nil, errors.New("invalid orgID: contains empty path segment")
		case ".":
			return nil, errors.New("invalid orgID: contains '.' path segment")
		case "..":
			return nil, errors.New("invalid orgID: contains '..' path segment")
		}
	}
	return []string{orgID}, nil
}

