func Unpack(r io.Reader, dst string) error {
	// Get absolute path of destination directory to prevent path traversal
	absDst, err := filepath.Abs(dst)
	if err != nil {
		return fmt.Errorf("failed to get absolute path of destination: %w", err)
	}

	// Decompress as we read.
	uncompressed, err := gzip.NewReader(r)
	if err != nil {
		return fmt.Errorf("failed to uncompress slug: %w", err)
	}
	defer uncompressed.Close()

	// Untar as we read.
	untar := tar.NewReader(uncompressed)

	// Unpackage all the contents into the directory.
	for {
		header, err := untar.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("failed to untar slug: %w", err)
		}

		// Remove leading slash from header name to prevent absolute paths
		name := strings.TrimPrefix(header.Name, "/")
		// Construct entry path using absolute destination
		entryPath := filepath.Join(absDst, name)
		// Clean entry path to remove relative components
		cleanedEntryPath := filepath.Clean(entryPath)

		// Get parent directory of the entry path
		parentDir := filepath.Dir(cleanedEntryPath)
		// Create parent directory (if not exists)
		if err := os.MkdirAll(parentDir, 0755); err != nil {
			return fmt.Errorf("failed to create directory %q: %w", parentDir, err)
		}

		// Resolve parent directory to its absolute physical path (handles symlinks)
		resolvedParent, err := filepath.EvalSymlinks(parentDir)
		if err != nil {
			return fmt.Errorf("failed to resolve parent directory %q: %w", parentDir, err)
		}

		// Compute resolved entry path (actual physical path)
		resolvedEntryPath := filepath.Join(resolvedParent, filepath.Base(cleanedEntryPath))

		// Check if resolved entry path is within the destination directory
		relEntry, err := filepath.Rel(absDst, resolvedEntryPath)
		if err != nil || strings.HasPrefix(relEntry, "..") {
			return fmt.Errorf("entry path %q resolves to outside destination directory %q", entryPath, absDst)
		}

		// Handle symlinks
		if header.Typeflag == tar.TypeSymlink {
			// Disallow absolute targets
			if filepath.IsAbs(header.Linkname) {
				return fmt.Errorf("invalid symlink (%q -> %q) has absolute target", header.Name, header.Linkname)
			}

			// Compute target path (relative to resolved parent directory)
			targetPath := filepath.Join(resolvedParent, header.Linkname)
			// Clean target path to remove relative components
			cleanedTargetPath := filepath.Clean(targetPath)

			// Check if target path is within the destination directory
			relTarget, err := filepath.Rel(absDst, cleanedTargetPath)
			if err != nil || strings.HasPrefix(relTarget, "..") {
				return fmt.Errorf("invalid symlink (%q -> %q) has external target", header.Name, header.Linkname)
			}

			// Create symlink at resolved entry path pointing to the original target (relative)
			if err := os.Symlink(header.Linkname, resolvedEntryPath); err != nil {
				return fmt.Errorf("failed to create symlink %q: %w", resolvedEntryPath, err)
			}

			continue
		}

		// Only process regular files and directories
		switch header.Typeflag {
		case tar.TypeDir:
			// Directories are already created by MkdirAll, skip
			continue
		case tar.TypeReg, tar.TypeRegA:
			// Proceed to create regular file
		default:
			return fmt.Errorf("unsupported file type %c for entry %q", header.Typeflag, header.Name)
		}

		// Open file at resolved entry path
		fh, err := os.Create(resolvedEntryPath)
		if err != nil {
			// Mimic tar's behavior for permission issues
			if os.IsPermission(err) {
				if chmodErr := os.Chmod(resolvedEntryPath, 0600); chmodErr != nil {
					return fmt.Errorf("failed to change permissions of %q: %w", resolvedEntryPath, chmodErr)
				}
				fh, err = os.Create(resolvedEntryPath)
			}
			if err != nil {
				return fmt.Errorf("failed to create file %q: %w", resolvedEntryPath, err)
			}
		}
		defer fh.Close()

		// Copy file contents
		if _, err := io.Copy(fh, untar); err != nil {
			return fmt.Errorf("failed to copy contents to %q: %w", resolvedEntryPath, err)
		}

		// Restore file mode
		mode := header.FileInfo().Mode()
		if err := os.Chmod(resolvedEntryPath, mode); err != nil {
			return fmt.Errorf("failed to set permissions on %q: %w", resolvedEntryPath, err)
		}
	}

	return nil
}

