                if (wordy) console.log('Ok 200');
                res.writeHead(200, {
                    'Content-Type': mime.lookup(filename) + ';' + mime.charsets.lookup(mime.lookup(filename)) 
                });
                res.write(file, 'binary');
                res.end();
            });
        });
    });
