module.exports = function(path, opts, cb) {
  const { execFile } = require('child_process');
  const { parse } = require('shell-quote');

  if (!cb) {
    cb = opts;
    opts = {};
  }

  var cmd = module.exports.cmd(path, opts);
  opts.timeout = opts.timeout || 5000;

  // Parse command string into arguments using shell-quote to handle quotes safely
  const argsArray = parse(cmd);
  const command = argsArray[0];
  const commandArgs = argsArray.slice(1);

  // Use execFile instead of exec to avoid shell injection
  execFile(command, commandArgs, opts, function(e, stdout, stderr) {
    if (e) { return cb(e); }
    if (stderr) { return cb(new Error(stderr)); }

    return cb(null, module.exports.parse(path, stdout, opts));
  });
};

