exports.killByPort = function (port) {
  var parsedPort = parseInt(port, 10);
  if (isNaN(parsedPort) || parsedPort < 1 || parsedPort > 65535) {
    throw new Error('Invalid port number');
  }

  var pids = [];
  try {
    var lsofResult = spawnSync('lsof', ['-t', `-i:${parsedPort}`]);
    pids = lsofResult.stdout.toString().trim().split('
').filter(pid => pid.length > 0);
  } catch (e) {
    // Handle error
  }

  if (pids.length > 0) {
    try {
      pids.forEach(function (pidStr) {
        var pid = parseInt(pidStr, 10);
        if (!isNaN(pid)) {
          spawnSync('kill', [pid.toString()]);
        }
      });
    } catch (e) {
      // Handle error
    }
  }
};

