    if (!isValidHostNameOrIP(host)) {
        console.error('[connection-tester] invalid host: ', host);
        host = undefined;
    }
    // validate port
    var originalPort = port;
    port = +port;
    if (!port || port < 0 || port > 65535) {
        console.error('[connection-tester] invalid port: ', originalPort);
        port = undefined;
    }

