    }

    if (typeof connectTimeout === 'number') {
        if (!port || !host) {
            var output = {
                success: false,
                error: 'invalid host/port'
            };

            if (callback) {
                return callback(null, output);
            } else {
                return output;
            }
        }
        if (callback) {
            return testAsync(host, port, connectTimeout, callback);
        } else {
            return testSync(host, port, connectTimeout);
        }
    }
}

