func (i *Instance) CreateNewConnection(listenPort int, username string, remoteIpAddr string, remotePort int) error {
	// Validate username to prevent command injection (defense-in-depth)
	if username != "" {
		// Disallow shell metacharacters and spaces
		if strings.ContainsAny(username, " ;&|()$`\"'<>\\/") {
			return errors.New("invalid username: contains forbidden characters (spaces or shell metacharacters not allowed)")
		}
	}

	// Build SSH command arguments (use -l for username to avoid shell interpretation)
	sshArgs := []string{"ssh", "-t"}
	if username != "" {
		sshArgs = append(sshArgs, "-l", username)
	}
	sshArgs = append(sshArgs, remoteIpAddr, "-p", strconv.Itoa(remotePort))

	// Configure gotty options (preserve original functionality)
	configPath := filepath.Join(filepath.Dir(i.ExecPath), ".gotty")
	title := fmt.Sprintf("%s@%s", username, remoteIpAddr)
	if remotePort != 22 {
		title = fmt.Sprintf("%s@%s:%d", username, remoteIpAddr, remotePort)
	}
	gottyOptions := []string{
		"-w",                  // Enable web socket
		"-p", strconv.Itoa(listenPort), // Listen port for gotty
		"--once",              // Exit after first connection
		"--config", configPath, // Gotty config file
		"--title-format", title, // Terminal title
	}

	// Combine gotty options and SSH arguments into a single slice (fixes Go variadic syntax)
	allArgs := append(gottyOptions, sshArgs...)

	// Execute gotty with direct arguments (no shell, eliminates injection risk)
	cmd := exec.Command(i.ExecPath, allArgs...)

	// Preserve original environment and output configuration
	cmd.Dir = filepath.Dir(i.ExecPath)
	cmd.Env = append(os.Environ(), "TERM=xterm")
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	// Run gotty in background (original goroutine logic)
	go func() {
		if err := cmd.Run(); err != nil {
			log.Printf("Got it execution error: %v", err)
		}
		i.Destroy()
	}()

	// Store connection state (original functionality)
	i.tty = cmd
	i.AssignedPort = listenPort
	i.RemoteAddr = remoteIpAddr
	i.RemotePort = remotePort

	// Create reverse proxy (original logic)
	path, err := url.Parse(fmt.Sprintf("http://127.0.0.1:%d", listenPort))
	if err != nil {
		return fmt.Errorf("proxy URL parse error: %w", err)
	}
	proxy := reverseproxy.NewReverseProxy(path)
	i.conn = proxy

	return nil
}

