func newMysqlQueryEndpoint(datasource *models.DataSource) (tsdb.TsdbQueryEndpoint, error) {
	logger := log.New("tsdb.mysql")

	protocol := "tcp"
	if strings.HasPrefix(datasource.Url, "/") {
		protocol = "unix"
	}

	// Build MySQL config
	config := mysql.Config{
		User:   datasource.User,
		Passwd: datasource.DecryptedPassword(),
		Net:    protocol,
		DBName: datasource.Database,
		Params: map[string]string{
			"collation":           "utf8mb4_unicode_ci",
			"parseTime":           "true",
			"loc":                 "UTC",
			"allowNativePasswords": "true",
		},
	}

	// Handle protocol-specific settings
	switch protocol {
	case "tcp":
		// Split and escape host for TCP protocol
		host, port, err := net.SplitHostPort(datasource.Url)
		if err != nil {
			return nil, fmt.Errorf("invalid TCP address: %w", err)
		}
		escapedHost := url.QueryEscape(host)
		config.Addr = fmt.Sprintf("%s:%s", escapedHost, port)
	case "unix":
		// Validate Unix socket path
		info, err := os.Stat(datasource.Url)
		if err != nil {
			return nil, fmt.Errorf("invalid Unix socket path: %w", err)
		}
		if info.Mode()&os.ModeSocket == 0 {
			return nil, fmt.Errorf("path is not a Unix socket: %s", datasource.Url)
		}
		config.Addr = datasource.Url
	default:
		return nil, fmt.Errorf("unsupported protocol: %s", protocol)
	}

	// Handle TLS config
	tlsConfig, err := datasource.GetTLSConfig()
	if err != nil {
		return nil, err
	}

	if tlsConfig.RootCAs != nil || len(tlsConfig.Certificates) > 0 {
		tlsConfigString := fmt.Sprintf("ds%d", datasource.Id)
		if err := mysql.RegisterTLSConfig(tlsConfigString, tlsConfig); err != nil {
			return nil, err
		}
		// Add TLS parameter to config
		config.Params["tls"] = tlsConfigString
	}

	// Generate connection string
	cnnstr := config.FormatDSN()

	// Log in DEV mode
	if setting.Env == setting.DEV {
		logger.Debug("getEngine", "connection", cnnstr)
	}

	// Configure SQL endpoint
	configSql := sqleng.SqlQueryEndpointConfiguration{
		DriverName:        "mysql",
		ConnectionString:  cnnstr,
		Datasource:        datasource,
		TimeColumnNames:   []string{"time", "time_sec"},
		MetricColumnTypes: []string{"CHAR", "VARCHAR", "TINYTEXT", "TEXT", "MEDIUMTEXT", "LONGTEXT"},
	}

	// Create result transformer
	rowTransformer := mysqlQueryResultTransformer{
		log: logger,
	}

	// Return new SQL endpoint
	return sqleng.NewSqlQueryEndpoint(&configSql, &rowTransformer, newMysqlMacroEngine(logger), logger)
}

