func UntarToDirectory(reader io.Reader, dst string) error {
	// Clean the destination directory path to its canonical form
	dstClean := filepath.Clean(dst)

	visitor := func(entry TarFileEntry) error {
		// Check if the entry name is an absolute path (bypasses dst)
		if filepath.IsAbs(entry.Header.Name) {
			return fmt.Errorf("absolute path not allowed in tar entry: %s", entry.Header.Name)
		}

		// Construct the target path and clean it to resolve relative components
		target := filepath.Join(dstClean, entry.Header.Name)
		targetClean := filepath.Clean(target)

		// Verify the target path is within the destination directory
		relPath, err := filepath.Rel(dstClean, targetClean)
		if err != nil {
			return fmt.Errorf("failed to verify path %s is within %s: %w", targetClean, dstClean, err)
		}
		if strings.HasPrefix(relPath, "../") {
			return fmt.Errorf("path traversal detected in tar entry: %s (resolves to %s)", entry.Header.Name, targetClean)
		}

		switch entry.Header.Typeflag {
		case tar.TypeDir:
			// Check if the directory exists; create it if not (using cleaned target path)
			if _, err := os.Stat(targetClean); err != nil {
				if err := os.MkdirAll(targetClean, 0755); err != nil {
					return fmt.Errorf("failed to create directory %s: %w", targetClean, err)
				}
			}

		case tar.TypeReg:
			// Open the file (using cleaned target path)
			f, err := os.OpenFile(targetClean, os.O_CREATE|os.O_RDWR, os.FileMode(entry.Header.Mode))
			if err != nil {
				return err
			}

			// Limit the reader to prevent decompression bomb attacks
			numBytes, err := io.Copy(f, io.LimitReader(entry.Reader, perFileReadLimit))
