func redirectTrailingSlash(c *Context) {
	req := c.Request
	p := req.URL.Path

	// Handle X-Forwarded-Prefix with validation
	prefixHeader := c.Request.Header.Get("X-Forwarded-Prefix")
	prefix := path.Clean(prefixHeader)

	valid := false
	if prefix != "." {
		// Check if prefix is not absolute
		if !strings.HasPrefix(prefix, "/") {
			// Check if prefix has no slashes (single segment)
			if !strings.Contains(prefix, "/") {
				// Check for invalid characters in prefix
				if !strings.Contains(prefix, "?") && !strings.Contains(prefix, "&") && !strings.Contains(prefix, "#") {
					valid = true
				}
			}
		}
	}

	if valid {
		// Use PathEscape instead of QueryEscape for path segments
		prefix = url.PathEscape(prefix)
		p = prefix + "/" + req.URL.Path
	} else {
		// Use original path if prefix is invalid or "."
		p = req.URL.Path
	}

	// Original logic for trailing slashes
	req.URL.Path = p + "/"
	if length := len(p); length > 1 && p[length-1] == '/' {
		req.URL.Path = p[:length-1]
	}
	redirectRequest(c)
}

