func redirectTrailingSlash(c *Context) {
	req := c.Request
	p := req.URL.Path
	prefixHeader := c.Request.Header.Get("X-Forwarded-Prefix")
	if prefixHeader != "" {
		// Reject absolute URLs (scheme or host) and invalid characters
		if !(strings.HasPrefix(prefixHeader, "http://") || strings.HasPrefix(prefixHeader, "https://") || strings.HasPrefix(prefixHeader, "//")) {
			if !strings.ContainsAny(prefixHeader, "?&#") {
				prefix := path.Clean(prefixHeader)
				// Prevent directory traversal
				if !strings.HasPrefix(prefix, "..") {
					// Escape prefix while preserving slashes
					prefix = url.PathEscape(prefix)
					prefix = strings.ReplaceAll(prefix, "%2F", "/")
					// Preserve original path concatenation logic
					p = prefix + "/" + req.URL.Path
				}
			}
		}
	}
	// Original trailing slash handling (preserve existing behavior)
	req.URL.Path = p + "/"
	if length := len(p); length > 1 && p[length-1] == '/' {
		req.URL.Path = p[:length-1]
	}
	redirectRequest(c)
}

