import * as dns from 'node:dns';
import { promisify } from 'node:util';
import type { ResourceDescriptor } from '../interfaces.js';
import logger from '../logger.js';

const lookup = promisify(dns.lookup);

function isPrivateIP(ip: string): boolean {
  const ipv4Private = /^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|169\.254\.|127\.)/;
  const ipv6Private = /^(fe80:|fc00:|fd00:)/i;
  return ipv4Private.test(ip) || ipv6Private.test(ip);
}

export async function lookupWebFinger(
  resource: URL | string,
): Promise<ResourceDescriptor | null> {
  if (typeof resource === "string") resource = new URL(resource);
  let protocol = "https:";
  let server: string;

  if (resource.protocol === "acct:") {
    const atPos = resource.pathname.lastIndexOf("@");
    if (atPos < 0) return null;
    server = resource.pathname.substring(atPos + 1);
    if (server === "") return null;
  } else {
    protocol = resource.protocol;
    server = resource.host;
  }

  // Resolve initial server hostname to IPs and check for private IPs
  try {
    const initialAddresses = await lookup(server, { all: true });
    for (const addr of initialAddresses) {
      if (isPrivateIP(addr.address)) {
        logger.error(
          "WebFinger server '{server}' resolves to private IP '{ip}', which is not allowed.",
          { server, ip: addr.address }
        );
        return null;
      }
    }
  } catch (error) {
    logger.error(
      "Failed to resolve WebFinger server '{server}': {error}",
      { server, error: (error as Error).message }
    );
    return null;
  }

  let url = new URL(`${protocol}//${server}/.well-known/webfinger`);
  url.searchParams.set("resource", resource.href);

  // Validate standard port for initial request
  const standardPort = protocol === "https:" ? "443" : "80";
  const initialPort = url.port || standardPort;
  if (initialPort !== standardPort) {
    logger.error(
      "Non-standard port '{initialPort}' is not allowed for protocol '{protocol}'.",
      { initialPort, protocol }
    );
    return null;
  }

  let redirected = 0;
  const MAX_REDIRECTION = 5;

  while (true) {
    logger.debug(
      "Fetching WebFinger resource descriptor from {url}...",
      { url: url.href }
    );
    let response: Response;

    try {
      response = await fetch(url, {
        headers: { Accept: "application/jrd+json" },
        redirect: "manual",
      });
    } catch (error) {
      logger.debug(
        "Failed to fetch WebFinger resource descriptor: {error}",
        { url: url.href, error: (error as Error).message }
      );
      return null;
    }

    if (response.status >= 300 && response.status < 400 && response.headers.has("Location")) {
      redirected++;
      if (redirected >= MAX_REDIRECTION) {
        logger.error(
          "Too many redirections ({redirections}) while fetching WebFinger resource descriptor.",
          { redirections: redirected }
        );
        return null;
      }

      const redirectedUrl = new URL(
        response.headers.get("Location")!,
        response.url || url.href
      );

      // Check if redirected protocol is different
      if (redirectedUrl.protocol !== url.protocol) {
        logger.error(
          "Redirected to a different protocol ({protocol} to {redirectedProtocol}) while fetching WebFinger resource descriptor.",
          { protocol: url.protocol, redirectedProtocol: redirectedUrl.protocol }
        );
        return null;
      }

      // Resolve redirected server hostname to IPs and check for private IPs
      const redirectedHostname = redirectedUrl.hostname;
      try {
        const redirectedAddresses = await lookup(redirectedHostname, { all: true });
        for (const addr of redirectedAddresses) {
          if (isPrivateIP(addr.address)) {
            logger.error(
              "Redirected WebFinger server '{redirectedHostname}' resolves to private IP '{ip}', which is not allowed.",
              { redirectedHostname, ip: addr.address }
            );
            return null;
          }
        }
      } catch (error) {
        logger.error(
          "Failed to resolve redirected WebFinger server '{redirectedHostname}': {error}",
          { redirectedHostname, error: (error as Error).message }
        );
        return null;
      }

      // Validate standard port for redirected request
      const redirectedProtocol = redirectedUrl.protocol;
      const redirectedStandardPort = redirectedProtocol === "https:" ? "443" : "80";
      const redirectedPort = redirectedUrl.port || redirectedStandardPort;
      if (redirectedPort !== redirectedStandardPort) {
        logger.error(
          "Non-standard port '{redirectedPort}' is not allowed for protocol '{redirectedProtocol}' in redirection.",
          { redirectedPort, redirectedProtocol }
        );
        return null;
      }

      // Update url for next iteration
      url = redirectedUrl;
      continue;
    }

    if (!response.ok) {
      logger.debug(
        "Failed to fetch WebFinger resource descriptor: {status} {statusText}.",
        {
          url: url.href,
          status: response.status,
          statusText: response.statusText,
        }
      );
      return null;
    }

    try {
      return await response.json() as ResourceDescriptor;
    } catch (e) {
      if (e instanceof SyntaxError) {
        logger.debug(
          "Failed to parse WebFinger resource descriptor as JSON: {error}",
          { error: (e as Error).message }
        );
        return null;
      }
      throw e;
    }
  }
}

