    const child = require('child_process').spawn(getInfoArgs[0], getInfoArgs.slice(1));
    let stdout = '';
    let stderr = '';

    // Collect output streams
    child.stdout.on('data', (chunk) => stdout += chunk);
    child.stderr.on('data', (chunk) => stderr += chunk);

    // Handle process exit
    child.on('close', (code) => {
      if (code !== 0) {
        return reject({
          message: "Failed to get PDF'S information",
