file.copy = function copy(srcpath, destpath, options) {
	// Resolve absolute paths for src and dest
	const resolvedSrc = path.resolve(srcpath);
	const resolvedDest = path.resolve(destpath);

	// Determine base directory (default to current working directory)
	const baseDir = path.resolve((options && options.baseDir) || process.cwd());

	// Validate source path is not a symbolic link
	const srcStats = fs.lstatSync(resolvedSrc);
	if (srcStats.isSymbolicLink()) {
		throw new Error(`Source path "${srcpath}" (resolved to "${resolvedSrc}") is a symbolic link, which is not allowed.`);
	}

	// Validate source path is within the allowed base directory
	if (!resolvedSrc.startsWith(baseDir)) {
		throw new Error(`Source path "${srcpath}" (resolved to "${resolvedSrc}") is outside the allowed directory "${baseDir}".`);
	}

	// Validate destination path is within the allowed base directory (even if it doesn't exist)
	if (!resolvedDest.startsWith(baseDir)) {
		throw new Error(`Destination path "${destpath}" (resolved to "${resolvedDest}") is outside the allowed directory "${baseDir}".`);
	}

	// Validate destination is not a symbolic link (if it exists)
	try {
		const destStats = fs.lstatSync(resolvedDest);
		if (destStats.isSymbolicLink()) {
			throw new Error(`Destination path "${destpath}" (resolved to "${resolvedDest}") is a symbolic link, which is not allowed.`);
		}
	} catch (err) {
		// Ignore error if destination does not exist
		if (err.code !== 'ENOENT') {
			throw err;
		}
	}

	// Original copy logic
	if (file.isDir(srcpath)) {
		// Create destination directory if it doesn't exist
		file.mkdir(destpath);
		// Recursively copy all files/directories in srcpath
		fs.readdirSync(srcpath).forEach(function(filepath) {
			copy(path.join(srcpath, filepath), path.join(destpath, filepath), options);
		});
	} else {
		// Copy single file using internal _copy method
		file._copy(srcpath, destpath, options);
	}
};

