res.location = function location(url) {
  var loc = url;

  // "back" is an alias for the referrer
  if (url === 'back') {
    loc = this.req.get('Referrer') || '/';
  }

  // Validate and sanitize the location URL to prevent open redirects
  try {
    // Parse URL (use base URL to handle relative paths)
    const parsed = new URL(loc, 'http://localhost');

    // Check for absolute URLs with invalid schemes
    if (parsed.protocol) {
      if (!['http:', 'https:'].includes(parsed.protocol)) {
        throw new Error('Invalid URL scheme. Only http/https are allowed.');
      }
    } else {
      // Check for valid relative paths (must start with /)
      if (!loc.startsWith('/')) {
        throw new Error('Relative URLs must start with /.');
      }
      // Block directory traversal in relative paths
      if (loc.startsWith('../')) {
        throw new Error('Directory traversal in relative URLs is not allowed.');
      }
    }

    // Sanitize to remove CRLF characters (prevent header injection)
    loc = loc.replace(/[\r\n]/g, '');
  } catch (err) {
    // Log error and default to safe URL if validation fails
    console.error('Invalid location URL:', err.message);
    loc = '/';
  }

  // Set the Location header with the sanitized URL
  this.set('Location', encodeurl(loc));

  return this;
};

