def get(self):
    from urllib.parse import urlparse
    uri = self.request.uri.rstrip('/')
    parsed_uri = urlparse(uri)
    if parsed_uri.scheme or parsed_uri.netloc:
        # Prevent open redirect by redirecting to root
        self.redirect('/')
