        // It's a file path, sanitize it
        const normalizedRuleSource = path.normalize(ruleSource);
        // Check for leading traversal sequences
        if (normalizedRuleSource.startsWith('../') || normalizedRuleSource.startsWith('..\\')) {
          throw new Error('Rule source path contains directory traversal sequences');
        }
        // Resolve relative to the current module's directory
        const baseDir = path.dirname(__filename);
        resolvedRuleSource = path.resolve(baseDir, normalizedRuleSource);
        // Check if resolved path is within baseDir
        if (!resolvedRuleSource.startsWith(baseDir)) {
          throw new Error('Rule source path is outside allowed directory');
        }
      } else {
        // It's a module name, use as-is
        resolvedRuleSource = ruleSource;
      }

      // Require the resolved rule source
      rules = require(resolvedRuleSource);
    } catch (error) {
      logger.warn({ ruleSource, error }, 'Unable to parse rule source, ignoring');
    }
  }

  if (!Array.isArray(rules)) {
    throw new Error(`Expected array of filter rules, got '${typeof rules}' instead.`);
  }

  logger.info({ rulesCount: rules.length }, 'loading new rules');

  // array of entries with
  const tests = rules.map(entry => {
    const keys = [];
    let { method, origin, path: rulePath, valid, stream } = entry;
    method = (method || 'get').toLowerCase();
    valid = valid || [];

    const bodyFilters = valid.filter(v => !!v.path && !v.regex);
    const bodyRegexFilters = valid.filter(v => !!v.path && !!v.regex);
    const queryFilters = valid.filter(v => !!v.queryParam);

    // now track if there's any values that we need to interpolate later
    const fromConfig = {};

    // slightly bespoke version of replace-vars.js
    const interpolatedPath = (rulePath || '').replace(/(\${.*?})/g, (_, match) => {
      const key = match.slice(2, -1); // ditch the wrappers
      fromConfig[key] = config[key] || '';
      return ':' + key;
    });

    origin = replace(origin, config);

    const normalizedRulePath = interpolatedPath[0] !== '/' ? `/${interpolatedPath}` : interpolatedPath;
    logger.info({ method, path: normalizedRulePath }, 'adding new filter rule');
    const regexp = pathRegexp(normalizedRulePath, keys);

    return (req) => {
      // check the request method
      if (req.method.toLowerCase() !== method && method !== 'any') {
        return false;
      }

      // Discard any fragments before further processing
      const mainURI = req.url.split('#')[0];

      // query params might contain additional "?"s, only split on the 1st one
      const parts = mainURI.split('?');
      let [url, querystring] = [parts[0], parts.slice(1).join('?')];

      // Sanitize URL to resolve directory traversal sequences
      const sanitizedUrl = path.normalize(url);
      // Block if any traversal sequences remain (shouldn't happen for absolute paths)
      if (sanitizedUrl.includes('..')) {
        return false;
      }

      const res = regexp.exec(sanitizedUrl);
      if (!res) {
        // no url match
        return false;
      }

      // reconstruct the url from the user config
      let reconstructedUrl = sanitizedUrl;
      for (let i = 1; i < res.length; i++) {
        const val = fromConfig[keys[i - 1].name];
        if (val) {
          reconstructedUrl = reconstructedUrl.replace(res[i], val);
        }
      }

      // if validity filters are present, at least one must be satisfied
      if (bodyFilters.length || bodyRegexFilters.length || queryFilters.length) {
        let isValid;

        let parsedBody;
        if (bodyFilters.length) {
          parsedBody = tryJSONParse(req.body);

          // validate against the body
          isValid = bodyFilters.some(({ path: filterPath, value }) => {
            return undefsafe(parsedBody, filterPath, value);
          });
        }

        if (!isValid && bodyRegexFilters.length) {
          parsedBody = parsedBody || tryJSONParse(req.body);

          // validate against the body by regex
          isValid = bodyRegexFilters.some(({ path: filterPath, regex }) => {
            try {
              const re = new RegExp(regex);
              return re.test(undefsafe(parsedBody, filterPath));
            } catch (error) {
              logger.error({ error, path: filterPath, regex }, 'failed to test regex rule');
              return false;
            }
          });
        }

        // no need to check query filters if the request is already valid
        if (!isValid && queryFilters.length) {
          const parsedQuerystring = qs.parse(querystring);

          // validate against the querystring
          isValid = queryFilters.some(({ queryParam, values }) => {
            return values.some(value => minimatch(parsedQuerystring[queryParam] || '', value));
          });
        }

        if (!isValid) {
          return false;
        }
      }

      logger.debug({ path: normalizedRulePath, origin, url: reconstructedUrl, querystring }, 'rule matched');

      querystring = querystring ? `?${querystring}` : '';
      return {
        url: `${origin}${reconstructedUrl}${querystring}`,
        auth: entry.auth && authHeader(entry.auth),
        stream
      };
    };
  });

  return (payload, callback) => {
    let res = false;
    logger.debug({ rulesCount: tests.length }, 'looking for a rule match');

    for (const test of tests) {
      res = test(payload);
      if (res) {
        break;
      }
    }
    if (!res) {
      return callback(Error('blocked'));
    }

    return callback(null, res);
  };
};

