  const rootAbs = nodePath.resolve(this._root);
  // Check if fsPath is within rootAbs
  const relative = nodePath.relative(rootAbs, fsPath);
  if (relative.startsWith('..') || nodePath.isAbsolute(relative)) {
    throw new Error('Path traversal detected');
  }
  // Return normalized clientPath (with forward slashes) and fsPath
  return {
    clientPath: nodePath.normalize(clientPath).replace(/\\/g, '/'),
