func CompileAndAuthorize(actorPermission Permission, toUpdate []Permission) (Permission, error) {
	// Calculate the actor's effective permission including all implied permissions
	effectiveActor := AddImplied(actorPermission)

	var permission Permission
	for _, update := range toUpdate {
