module.exports = path => {
  const pathModule = require('path');

  function customNormalize(pathStr) {
    if (!pathStr) return pathStr;
    const sep = pathStr.includes('\\') ? '\\' : '/';
    const segments = pathStr.split(sep);
    const stack = [];
    for (const segment of segments) {
      if (segment === '.') {
        continue;
      } else if (segment === '..') {
        if (stack.length > 0 && stack[stack.length - 1] !== '..') {
          stack.pop();
        } else {
          stack.push(segment);
        }
      } else {
        stack.push(segment);
      }
    }
    return stack.join(sep);
  }

  let root = '';
  let remainingPath = path;

  // Process absolute path components from the original path to preserve root structure
  while (pathModule.isAbsolute(remainingPath)) {
    const currentRoot = pathModule.parse(remainingPath).root;
    root += currentRoot;
    remainingPath = remainingPath.substr(currentRoot.length);
  }

  // Handle Windows drive letters in relative paths (add to root to prevent traversal)
  if (process.platform === 'win32') {
    const driveRegex = /^([A-Za-z]:)(.*)$/;
    let match;
    while ((match = driveRegex.exec(remainingPath))) {
      // Add the drive letter to the root
      root += match[1];
      // The remaining path is the part after the drive letter
      remainingPath = match[2];
      // Re-check if the remaining path is absolute (in case the part after the drive letter is absolute)
      while (pathModule.isAbsolute(remainingPath)) {
        const currentRoot = pathModule.parse(remainingPath).root;
        root += currentRoot;
        remainingPath = remainingPath.substr(currentRoot.length);
      }
    }
  }

  // Normalize the remaining path to resolve traversal sequences, preserve multiple slashes
  remainingPath = remainingPath ? customNormalize(remainingPath) : '';

  return [root, remainingPath];
}

