// addGroupsToSession fetches the user's actual GitLab groups and adds them to the session
func (p *GitLabProvider) addGroupsToSession(ctx context.Context, s *sessions.SessionState) error {
	// Check for valid access token
	if s.AccessToken == "" {
		return fmt.Errorf("no access token in session")
	}

	// Construct GitLab API URL for groups (using instance from LoginURL)
	baseURL := fmt.Sprintf("%s://%s", p.ProviderData.LoginURL.Scheme, p.ProviderData.LoginURL.Host)
	groupsURL := fmt.Sprintf("%s/api/v4/groups?membership=true", baseURL)

	// Create HTTP request with user's access token
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, groupsURL, nil)
	if err != nil {
		return fmt.Errorf("failed to create groups request: %w", err)
	}
	req.Header.Set("Authorization", fmt.Sprintf("Bearer %s", s.AccessToken))

	// Send request using provider's HTTP client
	resp, err := p.Client.Do(req)
	if err != nil {
		return fmt.Errorf("failed to send groups request: %w", err)
	}
	defer resp.Body.Close()

	// Validate response status
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("groups request failed with status %d", resp.StatusCode)
	}

	// Decode response to get user's groups
	type gitLabGroup struct {
		Path string `json:"path"`
	}
	var groups []gitLabGroup
	if err := json.NewDecoder(resp.Body).Decode(&groups); err != nil {
		return fmt.Errorf("failed to decode groups response: %w", err)
	}

	// Clear existing groups and add fetched ones (with "group:" prefix)
	s.Groups = nil
	for _, g := range groups {
		s.Groups = append(s.Groups, fmt.Sprintf("group:%s", g.Path))
	}

	return nil
}

