func WithAdditionalGIDs(userstr string) SpecOpts {
	return func(ctx context.Context, client Client, c *containers.Container, s *Spec) (err error) {
		// For LCOW or on Darwin additional GID's not supported
		if s.Windows != nil || runtime.GOOS == "darwin" {
			return nil
		}
		setProcess(s)
		setAdditionalGids := func(root string) error {
			var username string
			uid, err := strconv.Atoi(userstr)
			if err == nil {
				user, err := UserFromPath(root, func(u user.User) bool {
					return u.Uid == uid
				})
				if err != nil {
					if os.IsNotExist(err) || err == ErrNoUsersFound {
						return nil
					}
					return err
				}
				username = user.Name
			} else {
				username = userstr
			}
			// Clear existing supplementary groups first (FreeBSD fix)
			if runtime.GOOS == "freebsd" {
				if err := syscall.Setgroups(nil); err != nil {
					return err
				}
			}
			gids, err := getSupplementalGroupsFromPath(root, func(g user.Group) bool {
				// Exclude primary group
				if g.Name == username {
					return false
				}
				// Include groups where user is a member
				for _, entry := range g.List {
					if entry == username {
						return true
					}
				}
				return false
			})
			if err != nil {
				if os.IsNotExist(err) {
					return nil
				}
				return err
			}
			// Merge with existing additional gids (if any)
			if len(s.Process.User.AdditionalGids) > 0 {
				gids = append(gids, s.Process.User.AdditionalGids...)
			}
			// Deduplicate gids
			uniqueGids := make(map[uint32]bool)
			for _, gid := range gids {
				uniqueGids[gid] = true
			}
			var deduped []uint32
			for gid := range uniqueGids {
				deduped = append(deduped, gid)
			}
