func WithUsername(username string) SpecOpts {
	return func(ctx context.Context, client Client, c *containers.Container, s *Spec) (err error) {
		setProcess(s)
		if s.Linux != nil {
			if c.Snapshotter == "" && c.SnapshotKey == "" {
				if !isRootfsAbs(s.Root.Path) {
					return errors.New("rootfs absolute path is required")
				}
				user, err := UserFromPath(s.Root.Path, func(u user.User) bool {
					return u.Name == username
				})
				if err != nil {
					return err
				}
				// Fetch supplementary groups
				gids, err := getSupplementalGroupsFromPath(s.Root.Path, func(g user.Group) bool {
					if g.Name == user.Name {
						return false
					}
					for _, entry := range g.List {
						if entry == user.Name {
							return true
						}
					}
					return false
				})
				if err != nil && !os.IsNotExist(err) {
					return err
				}
				// Set UID/GID and additional groups
				 s.Process.User.UID = uint32(user.Uid)
				 s.Process.User.GID = uint32(user.Gid)
				 s.Process.User.AdditionalGids = gids
				 return nil
			}
			if c.Snapshotter == "" {
				return errors.New("no snapshotter set for container")
			}
			if c.SnapshotKey == "" {
				return errors.New("rootfs snapshot not created for container")
			}
			// Handle snapshotter case
			return mount.WithTempMount(ctx, client.SnapshotService(c.Snapshotter).Mounts(ctx, c.SnapshotKey)..., func(root string) error {
				user, err := UserFromPath(root, func(u user.User) bool {
					return u.Name == username
				})
				if err != nil {
					return err
				}
				// Fetch supplementary groups
				gids, err := getSupplementalGroupsFromPath(root, func(g user.Group) bool {
					if g.Name == user.Name {
						return false
					}
					for _, entry := range g.List {
						if entry == user.Name {
							return true
						}
					}
					return false
				})
				if err != nil && !os.IsNotExist(err) {
					return err
				}
				// Set UID/GID and additional groups
				 s.Process.User.UID = uint32(user.Uid)
				 s.Process.User.GID = uint32(user.Gid)
				 s.Process.User.AdditionalGids = gids
				 return nil
			})
		} else if s.Windows != nil {
				s.Process.User.Username = username
		} else {
			return errors.New("spec does not contain Linux or Windows section")
		}
		return nil
	}
}

