func (rc *resolutionContext) readUserTuple(ctx context.Context, backend storage.TupleBackend) (*openfgapb.TupleKey, error) {
	// Check contextual tuples first
	tk, ok := rc.contextualTuples.ReadUserTuple(rc.tk)
	if ok {
		if isValidTuple(tk, rc.model) {
			return tk, nil
		}
		// Fall through to backend check if invalid
	}

	// Check backend storage
	tuple, err := backend.ReadUserTuple(ctx, rc.store, rc.tk)
	if err != nil {
		return nil, err
	}
	tupleKey := tuple.GetKey()
	if !isValidTuple(tupleKey, rc.model) {
		return nil, fmt.Errorf("tuple %v violates authorization model type restrictions", tupleKey)
	}
	return tupleKey, nil
}

// isValidTuple verifies the tuple conforms to the authorization model's type definitions
func isValidTuple(tk *openfgapb.TupleKey, model *openfgapb.AuthorizationModel) bool {
	if tk == nil || model == nil {
		return false
	}
	// Extract object type from ID (e.g., "document:1" → "document")
	objectType, _, ok := strings.Cut(tk.GetObject(), ":")
	if !ok {
		return false
	}
	// Check if type exists in model
	typeDef := model.GetTypes()[objectType]
	if typeDef == nil {
		return false
