func RequireSignedJWT(ctx context.Context, key []byte) error {
	if len(key) > 0 {
		rawjwt, ok := JWTFromGRPCRequest(ctx)
		if !ok {
			return status.Error(codes.Unauthenticated, "unauthenticated")
		}

		if err := validateJWT(rawjwt, key); err != nil {
			log.Ctx(ctx).Debug().Err(err).Msg("rejected gRPC request due to invalid JWT")
			return status.Error(codes.Unauthenticated, "invalid JWT")
		}
	}
	return nil
}

func validateJWT(rawjwt string, key []byte) error {
	tok, err := jwt.ParseSigned(rawjwt)
	if err != nil {
		return err
	}

	var claims map[string]*jwt.NumericDate
	err = tok.Claims(key, &claims)
	if err != nil {
		return err
	} else if len(claims) != 1 || claims["exp"] == nil {
		return fmt.Errorf("expected exactly one claim (exp)")
	}

	if t := claims["exp"].Time(); time.Now().After(t) {
		return fmt.Errorf("JWT expired at %s", t.Format(time.DateTime))
	}
	return nil
}

patch:
func RequireSignedJWT(ctx context.Context, key []byte) error {
	if len(key) > 0 {
		rawjwt, ok := JWTFromGRPCRequest(ctx)
		if !ok {
			return status.Error(codes.Unauthenticated, "unauthenticated")
		}

		 tok, err := jwt.ParseSigned(rawjwt)
		if err != nil {
			return status.Errorf(codes.Unauthenticated, "invalid JWT: %v", err)
		}

		var claims struct {
			Expiry *jwt.NumericDate `json:"exp,omitempty"`
			Aud    interface{}      `json:"aud,omitempty"`
		}
		err = tok.Claims(key, &claims)
		if err != nil {
			return status.Errorf(codes.Unauthenticated, "invalid JWT: %v", err)
		}

		// Validate audience claim
		const expectedAudience = "databroker"
		if claims.Aud == nil {
			return status.Errorf(codes.Unauthenticated, "missing audience claim in JWT")
		}
		switch aud := claims.Aud.(type) {
		case string:
			if aud != expectedAudience {
				return status.Errorf(codes.Unauthenticated, "invalid audience in JWT: expected %q, got %q", expectedAudience, aud)
			}
		case []interface{}:
			found := false
			for _, a := range aud {
				if aStr, ok := a.(string); ok && aStr == expectedAudience {
					found = true
					break
				}
			}
			if !found {
				return status.Errorf(codes.Unauthenticated, "invalid audience in JWT: expected %q", expectedAudience)
			}
		default:
			return status.Errorf(codes.Unauthenticated, "invalid audience format in JWT: %T", aud)
		}

		// Validate expiration claim
		if claims.Expiry == nil {
			return status.Errorf(codes.Unauthenticated, "missing expiration claim in JWT")
		}
		if time.Now().After(claims.Expiry.Time()) {
			return status.Errorf(codes.Unauthenticated, "expired JWT")
		}
	}
	return nil
}

