func hostMatchesGlob(host string, domainGlob string) bool {
	// Normalize host: trim trailing dots and convert to lowercase
	normalizedHost := strings.TrimSuffix(host, ".")
	normalizedHost = strings.ToLower(normalizedHost)

	if domainGlob != "" && domainGlob[0] == '*' {
		suffix := domainGlob[1:]
		if strings.HasSuffix(normalizedHost, suffix) {
			return true
		}
	} else if domainGlob == normalizedHost {
		return true
	}
	return false
}

