	for _, d := range domains {
		// Normalize: trim trailing dots and convert to lowercase
		normalized := strings.TrimSuffix(d, ".")
		normalized = strings.ToLower(normalized)

		if normalized == "" {
			return fmt.Errorf("glob cannot be empty: %q", d)
		}

		// Check if glob starts with * but not with *. (e.g., "*example.com" is invalid)
		if !strings.HasPrefix(normalized, "*.\") && strings.HasPrefix(normalized, "*") {
