groundtruth.snippet:
function buildURL (source, reqBase) {
  const dest = new URL(source, reqBase)

  // if base is specified, source url should not override it
  if (reqBase) {
    if (!reqBase.endsWith('/') && dest.href.length > reqBase.length) {
      reqBase = reqBase + '/'
    }

    if (!dest.href.startsWith(reqBase)) {
      throw new Error('source must be a relative path string')
    }
  }

  return dest
}

patch:
function buildURL (source, reqBase) {
  const dest = new URL(source, reqBase);
  if (reqBase) {
    const baseUrl = new URL(reqBase);
    // Ensure the origin is the same (prevents absolute URLs with different origins)
    if (dest.origin !== baseUrl.origin) {
      throw new Error('source must be a relative path string (same origin as reqBase)');
    }
    // Ensure the path is within the base path (prevents escaping)
    const basePath = baseUrl.pathname;
    const destPath = dest.pathname;
    if (!destPath.startsWith(basePath)) {
      throw new Error('source path escapes the base path');
    }
  }
  return dest;
}

