function parse(str, options) {
  if (!options || typeof options !== 'object') {
    options = {};
  }
  str = str.trim();

  // Helper function to find the first unquoted occurrence of a character
  function findUnquotedChar(s, char) {
    let inQuotes = false;
    for (let i = 0; i < s.length; i++) {
      const c = s[i];
      if (c === '"') {
        inQuotes = !inQuotes;
      } else if (c === char && !inQuotes) {
        return i;
      }
    }
    return s.length;
  }

  // S4.1.1 Trailing semi-colons are not part of the specification.
  const TRAILING_SEMICOLON = /;+$/;
  const semiColonCheck = TRAILING_SEMICOLON.exec(str);
  if (semiColonCheck) {
    str = str.slice(0, semiColonCheck.index);
  }

  // Find the first unquoted ';' to split pairStr and unparsed
  const semiIndex = findUnquotedChar(str, ';');
  let pairStr = str.slice(0, semiIndex).trim();

  if (pairStr === '') {
    return;
  }

  // Handle key/value split based on options.loose
  let eqIndex = findUnquotedChar(pairStr, '=');
  let keyPart, valuePart;

  if (options.loose) {
    // Loose mode: allow missing '=' and empty key
    if (eqIndex === pairStr.length) {
      keyPart = pairStr.trim();
      valuePart = '';
    } else {
      keyPart = pairStr.slice(0, eqIndex).trim();
      valuePart = pairStr.slice(eqIndex + 1).trim();
    }
  } else {
    // Strict mode: require '=' and non-empty key
    if (eqIndex === pairStr.length) {
      return;
    }
    keyPart = pairStr.slice(0, eqIndex).trim();
    valuePart = pairStr.slice(eqIndex + 1).trim();
    if (keyPart === '') {
      return;
    }
  }

  // Handle quoted key (mimic original regex behavior)
  if (keyPart.startsWith('"') && keyPart.endsWith('"')) {
    keyPart = keyPart.slice(1, -1).trim();
  }

  // Handle quoted value (mimic original regex behavior)
  if (valuePart.startsWith('"') && valuePart.endsWith('"')) {
    valuePart = valuePart.slice(1, -1).trim();
  }

  // In strict mode, ensure key is not empty after unquoting
  if (!options.loose && keyPart === '') {
    return;
  }

  // Create cookie object with processed key and value
  const c = new Cookie();
  c.key = keyPart;
  c.value = valuePart;

  // Maintain original control characters check
  if (CONTROL_CHARS.test(c.key) || CONTROL_CHARS.test(c.value)) {
    return;
  }

  if (semiIndex === str.length) {
    return c;
  }

  // Process unparsed attributes
  let unparsed = str.slice(semiIndex).replace(/^\s*;\s*/, '').trim();

  if (unparsed.length === 0) {
    return c;
  }

  // Split unparsed into cookie_avs and filter out empty entries
  const cookie_avs = unparsed.split(/\s*;\s*/).filter(av => av.trim() !== '');

  while (cookie_avs.length) {
    const av = cookie_avs.shift();
    let av_sep = av.indexOf('=');
    let av_key, av_value;

    if (av_sep === -1) {
      av_key = av;
      av_value = null;
    } else {
      av_key = av.substr(0, av_sep);
      av_value = av.substr(av_sep + 1);
    }

    av_key = av_key.trim().toLowerCase();

    if (av_value) {
      av_value = av_value.trim();
    }

    switch (av_key) {
      case 'expires':
        if (av_value) {
          const exp = parseDate(av_value);
          if (exp) {
            c.expires = exp;
          }
        }
        break;
      case 'max-age':
        if (av_value && /^-?[0-9]+$/.test(av_value)) {
          const delta = parseInt(av_value, 10);
          c.setMaxAge(delta);
        }
        break;
      case 'domain':
        if (av_value) {
          const domain = av_value.trim().replace(/^\./, '');
          if (domain) {
            c.domain = domain.toLowerCase();
          }
        }
        break;
      case 'path':
        c.path = av_value && av_value[0] === "/" ? av_value : null;
        break;
      case 'secure':
        c.secure = true;
        break;
      case 'httponly':
        c.httpOnly = true;
        break;
      default:
