function parse(str, options) {
  if (!options || typeof options !== 'object') {
    options = {};
  }
  str = str.trim();

  // Helper function to find the first unquoted occurrence of a character
  function findUnquotedChar(s, char) {
    let inQuotes = false;
    for (let i = 0; i < s.length; i++) {
      const c = s[i];
      if (c === "") {
        inQuotes = !inQuotes;
      } else if (c === char && !inQuotes) {
        return i;
      }
    }
    return s.length;
  }

  // S4.1.1 Trailing semi-colons are not part of the specification.
  const TRAILING_SEMICOLON = /;+$/;
  const semiColonCheck = TRAILING_SEMICOLON.exec(str);
  if (semiColonCheck) {
    str = str.slice(0, semiColonCheck.index);
  }

  // Find the first unquoted ';' to split pairStr and unparsed
  const semiIndex = findUnquotedChar(str, ';');
  let pairStr = str.slice(0, semiIndex).trim();

  if (pairStr === '') {
    return;
  }

  // Handle key/value split based on options.loose
  let eqIndex = findUnquotedChar(pairStr, '=');
  let keyPart, valuePart;

  if (options.loose) {
    // Loose mode: allow missing '=' and empty key
    if (eqIndex === pairStr.length) {
      keyPart = pairStr.trim();
      valuePart = '';
    } else {
      keyPart = pairStr.slice(0, eqIndex).trim();
      valuePart = pairStr.slice(eqIndex + 1).trim();
    }
  } else {
    // Strict mode: require '=' and non-empty key
    if (eqIndex === pairStr.length) {
      return;
    }
    keyPart = pairStr.slice(0, eqIndex).trim();
    valuePart = pairStr.slice(eqIndex + 1).trim();
    if (keyPart === '') {
      return;
    }
  }

  // Handle quoted key (mimic original regex behavior)
  if (keyPart.startsWith('"') && keyPart.endsWith('"')) {
    keyPart = keyPart.slice(1, -1).trim();
  }

  // Handle quoted value (mimic original regex behavior)
  if (valuePart.startsWith('"') && valuePart.endsWith('"')) {
    valuePart = valuePart.slice(1, -1).trim();
  }

  // In strict mode, ensure key is not empty after unquoting
  if (!options.loose && keyPart === '') {
    return;
  }

  // Create cookie object with processed key and value
  const c = new Cookie();
  c.key = keyPart;
  c.value = valuePart;

