  if (CONTROL_CHARS.test(c.key) || CONTROL_CHARS.test(c.value)) {
    return;
  }

  if (semiIndex === str.length) {
    return c;
  }

  // Process unparsed attributes
  let unparsed = str.slice(semiIndex).replace(/^\s*;\s*/, '').trim();

  if (unparsed.length === 0) {
    return c;
  }

  // Split unparsed into cookie_avs and filter out empty entries
  const cookie_avs = unparsed.split(/\s*;\s*/).filter(av => av.trim() !== '');

  while (cookie_avs.length) {
    const av = cookie_avs.shift();
    let av_sep = av.indexOf('=');
    let av_key, av_value;

    if (av_sep === -1) {
      av_key = av;
      av_value = null;
    } else {
      av_key = av.substr(0, av_sep);
      av_value = av.substr(av_sep + 1);
    }

    av_key = av_key.trim().toLowerCase();

    if (av_value) {
      av_value = av_value.trim();
    }

    switch (av_key) {
      case 'expires':
        if (av_value) {
          const exp = parseDate(av_value);
          if (exp) {
            c.expires = exp;
          }
        }
        break;
      case 'max-age':
        if (av_value && /^-?[0-9]+$/.test(av_value)) {
          const delta = parseInt(av_value, 10);
          c.setMaxAge(delta);
        }
        break;
      case 'domain':
        if (av_value) {
          const domain = av_value.trim().replace(/^\./, '');
          if (domain) {
            c.domain = domain.toLowerCase();
          }
        }
        break;
      case 'path':
        c.path = av_value && av_value[0] === "/" ? av_value : null;
        break;
      case 'secure':
        c.secure = true;
        break;
      case 'httponly':
        c.httpOnly = true;
        break;
      default:
