func (fs *Filesystem) Delete(p string) error {
	wg := sync.WaitGroup{}
	resolved := fs.unsafeFilePath(p)
	if !fs.unsafeIsInDataDirectory(resolved) {
		return NewBadPathResolution(p, resolved)
	}

	if resolved == fs.Path() {
		return errors.New("cannot delete root server directory")
	}

	// Define a recursive function to check for symlinks pointing outside the data directory
	var checkSymlinks func(path string) error
	checkSymlinks = func(path string) error {
		st, err := os.Lstat(path)
		if err != nil {
			return errors.New("failed to stat path " + path + ": " + err.Error())
		}

		// Check if the file is a symlink
		if st.Mode()&os.ModeSymlink != 0 {
			target, err := os.Readlink(path)
			if err != nil {
				return errors.New("failed to read symlink target for " + path + ": " + err.Error())
			}
			// Resolve the target path relative to the symlink's directory
			dir := filepath.Dir(path)
			fullTarget := filepath.Join(dir, target)
			// Get absolute path to avoid relative path traversal attacks
			absTarget, err := filepath.Abs(fullTarget)
			if err != nil {
				return errors.New("failed to resolve absolute path for symlink target " + fullTarget + ": " + err.Error())
			}
			// Ensure the absolute target is within the data directory
			if !fs.unsafeIsInDataDirectory(absTarget) {
				return NewBadPathResolution(path, absTarget)
			}
		}

		// If the path is a directory, recursively check all its contents
		if st.IsDir() {
			entries, err := os.ReadDir(path)
			if err != nil {
				return errors.New("failed to read directory entries for " + path + ": " + err.Error())
			}
			for _, entry := range entries {
				entryPath := filepath.Join(path, entry.Name())
				if err := checkSymlinks(entryPath); err != nil {
					return err
				}
			}
		}

		return nil
	}

	var st os.FileInfo
	var err error
	if st, err = os.Lstat(resolved); err != nil {
		if !os.IsNotExist(err) {
			fs.error(err).Warn("error while attempting to stat file before deletion")
		}
	} else {
		// Check for symlinks in the path or its contents before deletion
		if err := checkSymlinks(resolved); err != nil {
			return err
		}
		// Update disk usage based on file type
		if !st.IsDir() {
			fs.addDisk(-st.Size())
		} else {
			wg.Add(1)
			go func(wg *sync.WaitGroup, st os.FileInfo, resolved string) {
				defer wg.Done()
				if s, err := fs.DirectorySize(resolved); err == nil {
					fs.addDisk(-s)
				}
			}(&wg, st, resolved)
		}
	}

	wg.Wait()

	return os.RemoveAll(resolved)
}

