function blockLanguage(block) {
  var classes = block.className + ' ';

  classes += block.parentNode ? block.parentNode.className : '';

  // language-* takes precedence over non-prefixed class names.
  const match = options.languageDetectRe.exec(classes);
  if (match) {
    const langName = match[1];
    // Prevent prototype pollution from malicious language names
    if (langName === '__proto__' || langName === 'constructor') {
      return 'no-highlight';
    }
    var language = getLanguage(langName);
    if (!language) {
      console.warn(LANGUAGE_NOT_FOUND.replace("{}", langName));
      console.warn("Falling back to no-highlight mode for this block.", block);
    }
    return language ? langName : 'no-highlight';
  }

  return classes
    .split(/\s+/)
    .find((_class) => {
      // Exclude malicious class names that could cause prototype pollution
      if (_class === '__proto__' || _class === 'constructor') {
        return false;
      }
      return shouldNotHighlight(_class) || getLanguage(_class);
    });
}

