module.exports = (env) => {
  function escapeSecretForRegex(secret) {
    return secret.split('').map((char) => {
      if (/[a-zA-Z0-9]/.test(char)) {
        return char;
      }
      const escapedChar = escapeRegExp(char);
      const encodedChar = encodeURIComponent(char);
      const encodedParts = encodedChar.split('');
      if (encodedParts.length === 3 && encodedParts[0] === '%') {
        const hex1 = encodedParts[1];
        const hex2 = encodedParts[2];
        const hex1Pattern = /[0-9]/.test(hex1) ? hex1 : `[${hex1.toUpperCase()}${hex1.toLowerCase()}]`;
        const hex2Pattern = /[0-9]/.test(hex2) ? hex2 : `[${hex2.toUpperCase()}${hex2.toLowerCase()}]`;
        const encodedCharCaseInsensitive = `%${hex1Pattern}${hex2Pattern}`;
        return `(${escapedChar}|${encodedCharCaseInsensitive})`;
      }
      return `(${escapedChar}|${encodedChar})`;
    }).join('');
  }

  const toReplace = Object.keys(env).filter((envVar) => {
    // https://github.com/semantic-release/semantic-release/issues/1558
    if (envVar === 'GOPRIVATE') {
