module.execute = function(arrParams) {
    return new Promise(function(resolve, reject) {
        var jarPath = path.join(__dirname, 'jar', 'key-sender.jar');

        // Parse command line options into an array to avoid shell injection
        function parseCommandLineOptions(optionsString) {
            const args = [];
            let currentArg = '';
            let inQuotes = false;

            for (const char of optionsString) {
                if (char === '"') {
                    inQuotes = !inQuotes;
                } else if (char === ' ' && !inQuotes) {
                    if (currentArg) {
                        args.push(currentArg);
                        currentArg = '';
                    }
                } else {
                    currentArg += char;
                }
            }

            // Add the last argument if any
            if (currentArg) {
                args.push(currentArg);
            }

            return args;
        }

        const commandLineOptions = module.getCommandLineOptions();
        const parsedOptions = parseCommandLineOptions(commandLineOptions);

        // Construct arguments array for execFile (avoids shell interpolation)
        const javaArgs = [
            '-jar',
            jarPath,
            ...arrParams,
            ...parsedOptions
        ];

        // Use execFile instead of exec to prevent command injection
        return execFile('java', javaArgs, {}, function(error, stdout, stderr) {
            if (error == null) {
                resolve(stdout, stderr);
            } else {
                reject(error, stdout, stderr);
            }
        });
    });
};

