trimvideo: (input, start, duration, output) => {
  const { execFile } = require("child_process");
  const fs = require("fs");
  const path = require("path");

  return new Promise(function(resolve, reject) {
    // Validate input is a non-empty string
    if (typeof input !== "string" || input.trim() === "") {
      reject(new Error("Invalid input file path"));
      return;
    }
    // Check if input file exists
    if (!fs.existsSync(input)) {
      reject(new Error("ffmpegdotjs could not find file"));
      return;
    }

    // Sanitize time values (start and duration) to prevent command injection
    function sanitizeTime(value) {
      if (typeof value !== "string" && typeof value !== "number") {
        throw new Error("Time value must be a string or number");
      }
      const strValue = String(value).trim();
      // Allow only digits, colons, and dots (valid for time formats like 10, 10.5, 00:00:10)
      const sanitized = strValue.replace(/[^0-9:.]/g, "");
      // Validate sanitized value is a valid time format
      if (!/^(\d+)(\.\d+)?$|^(\d+):(\d+):(\d+)(\.\d+)?$/.test(sanitized)) {
        throw new Error(`Invalid time value: ${strValue}`);
      }
      return sanitized;
    }

    // Sanitize output filename to prevent directory traversal and command injection
    function sanitizeOutput(filename) {
      if (typeof filename !== "string" || filename.trim() === "") {
        throw new Error("Output filename must be a non-empty string");
      }
      // Remove directory traversal characters (e.g., ../)
      const basename = path.basename(filename.trim());
      // Allow only alphanumeric, underscores, hyphens, and dots
      const sanitized = basename.replace(/[^a-zA-Z0-9_.-]/g, "");
      if (sanitized === "") {
        throw new Error("Invalid output filename");
      }
      return sanitized;
    }

    try {
      // Sanitize all inputs
      const sanitizedStart = sanitizeTime(start);
      const sanitizedDuration = sanitizeTime(duration);
      const sanitizedOutput = sanitizeOutput(output);
      const outputPath = `${sanitizedOutput}.mp4`;

      // Execute ffmpeg using execFile (safer than exec) with sanitized arguments
      execFile(
        "ffmpeg",
        [
          "-hide_banner",
          "-loglevel",
          "quiet",
          "-ss",
          sanitizedStart,
          "-i",
          input,
          "-t",
          sanitizedDuration,
          "-c",
          "copy",
          "-y",
          outputPath
        ],
        (error, stdout, stderr) => {
          if (error) {
            reject(error);
            return;
          }
          resolve(outputPath);
        }
      );
    } catch (err) {
      reject(err);
    }
  });
},

