def deny_uploads_containing_script_tag(uploaded_file):
    import lxml.etree as ET
    from django.core.exceptions import ValidationError
    from django.utils.translation import gettext_lazy as _

    dangerous_elements = {'script', 'embed', 'object', 'applet', 'iframe'}
    dangerous_attr_prefix = 'on'
    ns_map = {}

    try:
        # Use streaming parser to process file in chunks, prevent entity attacks
        parser = ET.iterparse(uploaded_file, events=('start', 'start-ns'), resolve_entities=False)
        for event, elem in parser:
            if event == 'start-ns':
                # Update namespace map to handle prefixed elements
                prefix, uri = elem
                ns_map[prefix] = uri
            elif event == 'start':
                # Get element name without namespace prefix
                local_name = ET.QName(elem).localname.lower()
                # Block dangerous elements (e.g., <script>, <embed>)
                if local_name in dangerous_elements:
                    raise ValidationError(_("File contains forbidden element: <{}>").format(local_name))
                # Block attributes that enable JavaScript execution (e.g., onload, onerror)
                for attr in elem.attrib:
                    attr_local_name = ET.QName(attr).localname.lower()
                    if attr_local_name.startswith(dangerous_attr_prefix):
                        raise ValidationError(_("File contains forbidden attribute: {} on element <{}>").format(attr, local_name))
    except ET.ParseError as e:
        # Reject invalid XML/SVG files to prevent malformed content bypass
        raise ValidationError(_("Invalid file format. Only valid SVG files are allowed. Error: {}").format(str(e)))
    finally:
        # Clean up parser resources
        if 'parser' in locals():
            parser = None

