func PDFHasImage(path string) bool {
	// Run pdffonts directly to avoid shell injection
	cmd := exec.Command("pdffonts", "-l", "5", path)
	out, err := cmd.Output()
	if err != nil {
		log.Println(err)
		return false
	}

	// Process output to replicate original pipeline behavior
	lines := strings.Split(string(out), "\n")
	var fonts []string
	for i, line := range lines {
		// Skip first two header lines
		if i < 2 {
			continue
		}
		// Extract first field (font name) from each line
		fields := strings.Fields(line)
		if len(fields) > 0 {
			fonts = append(fonts, fields[0])
		}
	}

	// Sort and deduplicate fonts (equivalent to sort | uniq)
	sort.Strings(fonts)
	var uniqueFonts []string
	for i, font := range fonts {
		if i == 0 || font != fonts[i-1] {
			uniqueFonts = append(uniqueFonts, font)
		}
	}

	// Return true if no unique fonts are found (original logic)
	return len(uniqueFonts) == 0
}

