patch:
var cleanUrl = function(url) { 
    var decodedUrl = decodeURIComponent(url);
    var normalizedPath = path.normalize(decodedUrl);
    // Reject absolute paths to prevent accessing files outside the base directory
    if (path.isAbsolute(normalizedPath)) {
        return '';
    }
    // Reject paths containing '..' to block directory traversal
    var pathParts = normalizedPath.split(path.sep);
    if (pathParts.includes('..')) {
        return '';
    }
    // Return the sanitized relative path
    return normalizedPath;
};

