func Init(ds model.DataStore) {
	once.Do(func() {
		log.Info("Setting Session Timeout", "value", conf.Server.SessionTimeout)

		// Retrieve master key from environment variable (required for encryption)
		masterKey := os.Getenv("NAVIDROME_MASTER_KEY")
		if masterKey == "" {
			log.Fatal("NAVIDROME_MASTER_KEY environment variable is not set. This is required to encrypt the JWT secret.")
		}
		// Decode master key from base64 (expected to be 32 bytes for AES-256)
		masterKeyBytes, err := base64.StdEncoding.DecodeString(masterKey)
		if err != nil {
			log.Fatal("Invalid NAVIDROME_MASTER_KEY: not base64 encoded", "error", err)
		}
		if len(masterKeyBytes) != 32 {
			log.Fatal("NAVIDROME_MASTER_KEY must be 32 bytes (256 bits) long")
		}

		// Function to encrypt a secret using AES-256-GCM
		encryptSecret := func(plaintext string) (string, error) {
			// Generate a 12-byte nonce (AES-GCM standard)
			nonce := make([]byte, 12)
			if _, err := rand.Read(nonce); err != nil {
				return "", fmt.Errorf("failed to generate nonce: %w", err)
			}
			// Create AES-GCM cipher
			block, err := aes.NewCipher(masterKeyBytes)
			if err != nil {
				return "", fmt.Errorf("failed to create cipher: %w", err)
			}
			gcm, err := cipher.NewGCM(block)
			if err != nil {
				return "", fmt.Errorf("failed to create GCM: %w", err)
			}
			// Encrypt the plaintext
			ciphertext := gcm.Seal(nil, nonce, []byte(plaintext), nil)
			// Combine nonce and ciphertext, then base64 encode
			encryptedData := append(nonce, ciphertext...)
			return base64.StdEncoding.EncodeToString(encryptedData), nil
		}

		// Function to decrypt a secret using AES-256-GCM
		decryptSecret := func(encrypted string) (string, error) {
			// Decode base64-encoded encrypted data
			data, err := base64.StdEncoding.DecodeString(encrypted)
			if err != nil {
				return "", fmt.Errorf("failed to decode encrypted data: %w", err)
			}
			// Check minimum length (12-byte nonce + 1-byte ciphertext)
			if len(data) < 13 {
				return "", fmt.Errorf("invalid encrypted data length")
			}
			// Split into nonce (first 12 bytes) and ciphertext (remaining)
			nonce := data[:12]
			ciphertext := data[12:]
			// Create AES-GCM cipher
			block, err := aes.NewCipher(masterKeyBytes)
			if err != nil {
				return "", fmt.Errorf("failed to create cipher: %w", err)
			}
			gcm, err := cipher.NewGCM(block)
			if err != nil {
				return "", fmt.Errorf("failed to create GCM: %w", err)
			}
			// Decrypt the ciphertext
			plaintext, err := gcm.Open(nil, nonce, ciphertext, nil)
			if err != nil {
				return "", fmt.Errorf("failed to decrypt: %w", err)
			}
			return string(plaintext), nil
		}

		// Retrieve the stored secret from the database
		secretStored, err := ds.Property().Get(consts.JWTSecretKey)
		if err != nil {
			log.Error("Failed to retrieve JWT secret from database", "error", err)
			// Use a temporary secret (not stored) if database access fails
			secret := uuid.NewString()
			log.Error("Using a temporary JWT secret (not stored). Fix the database issue to use a persistent secret.", "error", err)
			Secret = []byte(secret)
			TokenAuth = jwtauth.New("HS256", Secret, nil)
			return
		}

		var secret string

		if secretStored == "" {
			// No secret found: use a temporary one (not stored)
			secret = uuid.NewString()
			log.Error("No JWT secret found in DB. Using a temporary one (not stored). Please set a persistent encrypted secret in the database.")
		} else {
			// Try to decrypt the stored secret
			decrypted, err := decryptSecret(secretStored)
			if err == nil {
				// Successfully decrypted: use the secret
				secret = decrypted
			} else {
				// Failed to decrypt: assume plaintext and migrate to encrypted storage
				log.Info("Migrating plaintext JWT secret to encrypted storage")
				// Encrypt the plaintext secret
				encrypted, err := encryptSecret(secretStored)
				if err != nil {
					log.Fatal("Failed to encrypt plaintext JWT secret during migration", "error", err)
				}
				// Store the encrypted secret back to the database
				if err := ds.Property().Set(consts.JWTSecretKey, encrypted); err != nil {
					log.Fatal("Failed to store encrypted JWT secret during migration", "error", err)
				}
				// Use the original plaintext secret (one-time migration)
				secret = secretStored
				log.Info("Successfully migrated JWT secret to encrypted storage")
			}
		}

		// Set the secret and initialize JWT auth
		Secret = []byte(secret)
		TokenAuth = jwtauth.New("HS256", Secret, nil)
	}) 
}

